-- Athena saved query (Product_B2C_Intl)
-- ID: 41a37282-e1ad-4d34-b537-bb2f5e8e7bc1
-- Name: priceVariantAB Median SL Visits - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH srp_deduped AS ( SELECT DISTINCT s.mri_session_id, s.route_id, s.user_type, s.os, s.channel, s.country, CASE WHEN contains(channel_exp_info, 'priceVariantAB:V0') THEN 'V0' WHEN contains(channel_exp_info, 'priceVariantAB:V1') THEN 'V1' WHEN contains(channel_exp_info, 'priceVariantAB:V2') THEN 'V2' WHEN contains(channel_exp_info, 'priceVariantAB:V3') THEN 'V3' WHEN contains(channel_exp_info, 'priceVariantAB:V4') THEN 'V4' ELSE 'others' END AS exp_Variant, -- , s.cohort_type, s.cohort_display_type, doj, -- CAST(HOUR(AT_TIMEZONE(s.__time, 'Asia/Kolkata'))AS INT) AS day_hour, CAST(DATE_TRUNC('day', at_timezone(s.__time, 'Asia/Kolkata')) AS DATE) AS doi FROM "user_interaction"."search_route_details" s WHERE s.__time >= TIMESTAMP '2026-03-31 18:30:00' AND s.__time < TIMESTAMP '2026-04-06 18:30:00' AND s.channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') AND tp_channel = 'INVALID' AND akamai_bot IS NULL AND s.country = 'IND' ), -- Get the count of unique SL visits per session sl_stats AS ( SELECT mri_session_id, user_origin, COUNT(DISTINCT route_id) as total_sl_visits FROM "user_interaction"."seat_layout_details" WHERE __time >= TIMESTAMP '2026-03-31 18:30:00' AND __time < TIMESTAMP '2026-04-06 18:30:00' AND country = 'IND' -- AND channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') -- AND tp_channel = 'INVALID' AND akamai_bot IS NULL GROUP BY 1 , 2 ), -- Only get sessions that actually confirmed confirm_sessions AS ( SELECT DISTINCT mri_session_id, route_id FROM "user_interaction"."confirm_order_details" WHERE __time >= TIMESTAMP '2026-03-31 18:30:00' AND __time < TIMESTAMP '2026-04-06 18:30:00' AND country = 'IND' -- AND channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') -- AND tp_channel = 'INVALID' AND akamai_bot IS NULL AND status = 200 AND tin IS NOT NULL AND tin NOT IN ('', 'null') ), -- Combine everything at the SESSION level final_session_list AS ( SELECT srp.doi, conf.mri_session_id, srp.exp_Variant, UPPER(srp.user_type) as user_type, CASE WHEN srp.os IS NULL THEN srp.channel ELSE srp.os END AS saleschannel, sls.total_sl_visits FROM srp_deduped srp LEFT JOIN sl_stats sls ON conf.mri_session_id = sls.mri_session_id LEFT JOIN confirm_sessions conf ON conf.mri_session_id = srp.mri_session_id AND conf.route_id = srp.route_id ) -- Now calculate the median SELECT doi, exp_Variant, user_type, saleschannel, COUNT(DISTINCT mri_session_id) as confirm_sessions_count, AVG(total_sl_visits) avg_sl_visits, approx_percentile(total_sl_visits, 0.5) AS median_sl_visits, approx_percentile(total_sl_visits, 0.1) AS top_10_sl_visits, approx_percentile(total_sl_visits, 0.9) AS low_10_sl_visits FROM final_session_list GROUP BY 1, 2, 3, 4 ORDER BY saleschannel, exp_Variant, user_type DESC;
